#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/aff3ct/codec_help.h>

void bind_codec_help(py::module& m)
{
    m.def("codec_help",
          &::gr::aff3ct::codec_help,
          py::arg("code"),
          "Help of the AFF3CT options accepted by codec_encoder and codec_decoder for a code "
          "type (e.g. 'POLAR'), as printed by the simulator.");
}
